def transform(grid):
    h, w = len(grid), len(grid[0])
    # Collect row markers (the non-background color in each row), then
    # repeat their colors vertically, aligned by the marker's row index.
    markers = {}
    for r, row in enumerate(grid):
        for v in row:
            if v:
                markers[r] = v
                break
    if not markers:
        return [row[:] for row in grid]
    period = len(markers)
    out = []
    for r in range(h):
        src = r % period
        if src not in markers:
            # Sparse marker rows define the periodic sequence by row alignment.
            src = min(markers, key=lambda x: (x - r) % period)
        out.append([markers[src]] * w)
    return out
